-- The signing secret is generated by clients and never uploaded.
CREATE TABLE admin_server_identity (
    singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    server_id UUID NOT NULL DEFAULT gen_random_uuid()
);
INSERT INTO admin_server_identity(singleton) VALUES(TRUE);
ALTER TABLE server_administrators ADD COLUMN signing_public_key BYTEA CHECK (octet_length(signing_public_key)=32);
ALTER TABLE admin_sessions ADD COLUMN signing_public_key BYTEA CHECK (octet_length(signing_public_key)=32);
-- Pre-upgrade sessions must not bypass the new proof.
DELETE FROM admin_sessions;
CREATE TABLE admin_key_challenges (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES server_administrators(user_id) ON DELETE CASCADE,
    auth_session UUID NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    purpose TEXT NOT NULL CHECK(purpose IN ('unlock','rotate')),
    public_key BYTEA NOT NULL CHECK(octet_length(public_key)=32),
    nonce TEXT NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL DEFAULT now()+interval '2 minutes',
    UNIQUE(user_id,auth_session)
);
CREATE INDEX admin_key_challenges_expiry ON admin_key_challenges(expires_at);
